SELECT p.id, p.title, p.latitude, p.longitude, p.date, p.denominator, p.numerator, p.price, p.place, p.is_completed, ( SELECT COUNT(*) FROM nthing.like b WHERE true AND b.user_id = #{userId} AND b.purchase_id = p.id ) AS is_liked, ( SELECT save_name FROM nthing.purchase_file WHERE true AND purchase_id = p.id AND delete_yn = false ORDER BY id LIMIT 1 ) AS image, ST_Distance_Sphere(@location, POINT(p.longitude, p.latitude)) AS distance FROM nthing.purchase AS p WHERE true AND p.delete_yn = 0 AND ST_Distance_Sphere(@location, POINT(p.longitude, p.latitude)) <= #{radius}
AND (p.title LIKE CONCAT('%', #{search_keyword}, '%') OR p.description LIKE CONCAT('%', #{search_keyword}, '%'))
AND p.is_completed = false
ORDER BY ${sort}
ORDER BY -p.created_at

SELECT p.id, p.title, p.latitude, p.longitude, p.date, p.denominator, p.numerator, p.price, p.place, p.is_completed, ( SELECT COUNT(*) FROM nthing.like b WHERE true AND b.user_id = #{userId} AND b.purchase_id = p.id ) AS is_liked, ( SELECT save_name FROM nthing.purchase_file WHERE true AND purchase_id = p.id AND delete_yn = false ORDER BY id LIMIT 1 ) AS image FROM nthing.purchase AS p WHERE true AND p.delete_yn = false AND p.manager_id = #{userId}
AND (p.title LIKE CONCAT('%', #{search_keyword}, '%') OR p.description LIKE CONCAT('%', #{search_keyword}, '%'))
AND p.is_completed = true
ORDER BY ${sort}
ORDER BY -p.created_at

SELECT
    p.id, p.title, p.description, p.latitude, p.longitude, p.date, p.denominator, p.numerator,
    p.is_completed, p.price, p.place, p.created_at, p.updated_at, p.category_id, p.manager_id,
    c.name AS category_name,
    (
        SELECT COUNT(*)
        FROM nthing.purchase_user pu
        WHERE true
            AND pu.user_id = #{userId}
            AND pu.purchase_id = #{id}
    ) AS is_joined,
    (
        SELECT COUNT(*)
        FROM nthing.like b
        WHERE true
            AND b.user_id = #{userId}
            AND b.purchase_id = #{id}
    ) AS is_liked,
    (
        SELECT COUNT(*)
        FROM nthing.purchase p
        WHERE true
            AND p.id = #{id}
            AND p.manager_id = #{userId}
    ) AS is_manager
FROM
    nthing.purchase AS p
        LEFT JOIN category c ON p.category_id = c.id
        LEFT JOIN user u ON p.manager_id = u.id
WHERE TRUE
    AND p.id = #{id}
    AND p.delete_yn = 0

SELECT COUNT(*) > 0 AS isExist
FROM nthing.purchase
WHERE id = #{id}
    AND manager_id = #{userId}
    AND delete_yn = 0

SELECT p.id, p.title, p.latitude, p.longitude, p.date, p.denominator, p.numerator, p.price, p.place, p.is_completed, ( SELECT COUNT(*) FROM nthing.like b WHERE true AND b.user_id = #{userId} AND b.purchase_id = p.id ) AS is_liked, ( SELECT save_name FROM nthing.purchase_file WHERE true AND purchase_id = p.id AND delete_yn = false ORDER BY id LIMIT 1 ) AS image FROM nthing.purchase_user AS pu LEFT JOIN nthing.purchase AS p ON pu.purchase_id = p.id WHERE true AND p.delete_yn = false AND pu.user_id = #{userId}
AND (p.title LIKE CONCAT('%', #{search_keyword}, '%') OR p.description LIKE CONCAT('%', #{search_keyword}, '%'))
AND p.is_completed = true
ORDER BY ${sort}
ORDER BY -p.created_at

